const item = $input.item.json;
const rawError = item && item.error;
const rawMessage = typeof rawError === 'string' ? rawError : (rawError && rawError.message) ? rawError.message : 'Unbekannter Fehler';
return [{ json: { ...item, valid: false, errorMessage: 'Bei der Kommunikation mit dem lokalen Ollama-Modell ist ein Fehler aufgetreten. Bitte versuchen Sie es später erneut.\n\nDetails: ' + rawMessage } }];

const parsed = $input.item.json;
const original = $('Spielerprofil: Positionspool ermitteln').first().json;
const playerProfile = { simulated: false, position: parsed.position, role: parsed.role, weightedCriteria: parsed.weightedCriteria, constraints: parsed.constraints, reasoning: parsed.reasoning };
return [{ json: { ...original, playerProfile } }];

const item = $input.item.json;
const p = item.playerProfile;
const errors = [];
if (!p || typeof p !== 'object') { errors.push('playerProfile fehlt oder ist kein Objekt.'); } else {
  if (!p.position) errors.push('playerProfile.position fehlt.');
  if (!p.role) errors.push('playerProfile.role fehlt.');
  if (!p.reasoning) errors.push('playerProfile.reasoning fehlt.');
  if (!Array.isArray(p.weightedCriteria) || p.weightedCriteria.length === 0) errors.push('playerProfile.weightedCriteria fehlt oder ist leer.');
  else if (p.weightedCriteria.some((c) => !c.criterion || typeof c.weight !== 'number')) errors.push('playerProfile.weightedCriteria enthaelt einen Eintrag ohne criterion oder numerisches weight.');
  if (!Array.isArray(p.constraints)) errors.push('playerProfile.constraints fehlt oder ist kein Array.');
  else if (p.constraints.some((c) => !c || !['age','marketValueMEUR'].includes(c.field) || !['max','min'].includes(c.operator) || typeof c.value !== 'number' || !Number.isFinite(c.value))) errors.push('playerProfile.constraints enthaelt einen Eintrag ohne gueltiges field/operator/numerisches value.');
  if (p.position) {
    const DEFENSIVE_POSITIONS=['Innenverteidiger','Linksverteidiger','Rechtsverteidiger','Defensives Mittelfeld'];
    const ATTACKING_POSITIONS=['Offensives Mittelfeld','Linksaußen','Mittelstürmer'];
    const ALL_POSITIONS=['Innenverteidiger','Linksverteidiger','Rechtsverteidiger','Defensives Mittelfeld','Zentrales Mittelfeld','Offensives Mittelfeld','Linksaußen','Mittelstürmer'];
    const diagnosisCategory=(item.teamDiagnosis&&item.teamDiagnosis.diagnosisCategory)||'no_data';
    const allowedPositions=diagnosisCategory==='defensive'?DEFENSIVE_POSITIONS:diagnosisCategory==='offensive'?ATTACKING_POSITIONS:ALL_POSITIONS;
    if(!allowedPositions.includes(p.position)) errors.push(`playerProfile.position ('${p.position}') passt nicht zur Diagnosekategorie '${diagnosisCategory}' (erlaubt: ${allowedPositions.join(', ')}).`);
  }
}
const valid=errors.length===0;
return [{json:{...item,valid,errorMessage:valid?undefined:'Das Spielerprofil ist ungueltig und wird nicht fuer die Spielersuche verwendet.\n\n'+errors.join('\n')}}];

const MAX_REVIEW_ROUNDS = 3;
const item = $input.item.json;
const priorBrief = item.scoutingBrief;
const feedbackHistory = Array.isArray(priorBrief && priorBrief.feedbackHistory) ? [...priorBrief.feedbackHistory] : [];
if (item.reviewDecision === 'Request Changes' && priorBrief) feedbackHistory.push({ round: priorBrief.reviewRound, feedback: item.reviewFeedback || '' });
const teamDiagnosis=item.teamDiagnosis||{}; const playerProfile=item.playerProfile||{};
const scoutingBrief={problem:teamDiagnosis.mainProblem,targetPosition:playerProfile.position,role:playerProfile.role,reasoning:playerProfile.reasoning,weightedCriteria:playerProfile.weightedCriteria,constraints:playerProfile.constraints,uncertainties:Array.isArray(teamDiagnosis.uncertainties)?teamDiagnosis.uncertainties:[],reviewRound:feedbackHistory.length+1,maxReviewRounds:MAX_REVIEW_ROUNDS,feedbackHistory};
return [{json:{...item,scoutingBrief}}];

